        }
        .auto-margin {
            margin: auto;
        }
        .main-container {
            max-width: 588px;
        }
        .main-body {
            background-color: #ffffff;
            margin-bottom: 20px;
            padding: 20px;
            max-width: 550px;
            text-align: center;
            margin-left: auto;
            margin-right: auto;
        }
    </style>
</head>
